import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.C2zB12QK.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"tarsi","text":"The release plane","tagline":"Changelog → semver bump → tag → publish — one ops wire for humans, agents, and campaigns.","actions":[{"theme":"brand","text":"Get started","link":"/tutorials/getting-started"},{"theme":"alt","text":"Release semantics","link":"/explanation/release-semantics"}]},"features":[{"title":"Plan, don\'t mutate","details":"`release` is dry-run by default — real mutation requires `dry_run: false`, the same `--yes` a human would give."},{"title":"Per-unit tags","details":"`{unit}-v{semver}` tags attribute commits by path and version each release unit independently."},{"title":"Profiles as packs","details":"Org conventions ship as `type: tarsi` tamias packs — layered config, versioned by the store."},{"title":"One wire","details":"ndjson ops over `tarsi-serve` — agents, peregrin campaigns, and humans speak the same protocol."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function n(o,e,l,d,h,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? View /tarsi/llms.txt for optimized Markdown documentation, or /tarsi/llms-full.txt for full documentation bundle</div><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Tarsi is the org&#39;s release plane: changelog → semver bump → tag → publish, exposed as <code>tarsi-serve</code> ndjson ops. Repo config is <code>tarsi.toml</code>; org conventions ride <code>type: tarsi</code> tamias profile packs; there is deliberately no <code>tarsi</code> CLI.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Every repo was reinventing release plumbing — changelog rendering, commit→bump inference, tag schemes, publish ordering. Tarsi makes release <em>semantics</em> a shared, deterministic ops surface that humans, agents, and peregrin campaigns all drive identically, with dry-run as the default so probing never mutates.</p><h2 id="boundary" tabindex="-1">Boundary <a class="header-anchor" href="#boundary" aria-label="Permalink to &quot;Boundary&quot;">​</a></h2><ul><li><strong>Owns:</strong> release semantics — plans, bumps, changelogs, tags, publish orchestration.</li><li><strong>Doesn&#39;t own:</strong> orchestration timing/approval (<a href="https://9aia.com/peregrin/" target="_blank" rel="noreferrer">peregrin</a>), distribution (<a href="https://9aia.com/tamias/" target="_blank" rel="noreferrer">tamias</a>), git itself (<a href="https://github.com/9aia/lasius" target="_blank" rel="noreferrer">lasius-vcs</a>).</li></ul><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to…</th><th>Go to</th></tr></thead><tbody><tr><td>Cut a real release end to end</td><td><a href="/tarsi/tutorials/getting-started.html">Tutorial</a></td></tr><tr><td>Do a task (write tarsi.toml, author a profile, drive ops)</td><td><a href="/tarsi/how-to/">How-to</a></td></tr><tr><td>Understand the design (ops wire, semantics, boundaries)</td><td><a href="/tarsi/explanation/">Explanation</a></td></tr><tr><td>Look up an op, config field, or pack layout</td><td><a href="/tarsi/reference/">Reference</a></td></tr></tbody></table>',9)])])}const m=t(i,[["render",n]]);export{u as __pageData,m as default};
